	bb_bbsid
,	bb_or_idx
,	bb_type
,	bb_title
,	bb_content
,	bb_seq
,	bb_hit
,	bb_notice
,	bb_open
,	bb_confirm
,	bb_status
,	bb_open_type
,	bb_co_idx
,	bb_reg_date
,	bb_reg_id
,	bb_reg_ip
) VALUES (
	#{bbBbsid}
,	#{bbOrIdx}
,	#{bbType}
,	#{bbTitle}
,	#{bbContent}
,	#{bbSeq}
,	#{bbHit}
,	#{bbNotice}
,	#{bbOpen}
,	#{bbConfirm}
,	#{bbStatus}
,	#{bbOpenType}
,	#{bbCoIdx}
,	CURRENT_TIMESTAMP
,	#{bbRegId}
,	#{bbRegIp}
)

