UPDATE 
	sianadb.market.bbs
SET
	bb_mod_date = CURRENT_TIMESTAMP
,	bb_mod_id = #{bbModId}
,	bb_mod_ip = #{bbModIp}
,	bb_content = #{bbContent}
,	bb_notice = #{bbNotice}
,	bb_or_idx = #{bbOrIdx}
,	bb_title = #{bbTitle}
,	bb_open = #{bbOpen}
WHERE 1 = 1
AND bb_idx = #{bbIdx}
